import{_ as o,o as t,c as e,a5 as r}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"Konado 脚本","description":"","frontmatter":{"title":"Konado 脚本","order":1},"headers":[],"relativePath":"zh/latest/tutorial/script/konado-script.md","filePath":"zh/latest/tutorial/script/konado-script.md","lastUpdated":1788455378000}'),i={name:"zh/latest/tutorial/script/konado-script.md"};function d(n,a,l,c,s,p){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="konadoscript" tabindex="-1">KonadoScript <a class="header-anchor" href="#konadoscript" aria-label="Permalink to &quot;KonadoScript&quot;">​</a></h1><p>KonadoScript 是一种为视觉小说量身定制的创作语言（文件后缀为 .ks）。</p><p>你可以把它想象成一种更强大、更结构化的“小说剧本”：开发者无需编写复杂代码，就能控制剧情对话、角色立绘、背景切换、音乐音效，以及故事分支和选项。</p><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><p>KonadoScript 的核心设计理念是将<strong>故事内容</strong>与<strong>程序逻辑</strong>分离：</p><ul><li>编剧专注于叙事内容，无需编程知识</li><li>程序员专注于引擎开发，无需介入故事创作</li><li>资源管理（图片、音频）通过标识符引用，与脚本解耦</li><li>模块化指令集，易于扩展新功能</li><li>兼容版本控制系统（Git等）</li><li>文本格式天生跨平台</li><li>资源引用与平台无关</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="_1-解析错误如何处理" tabindex="-1">1. 解析错误如何处理 <a class="header-anchor" href="#_1-解析错误如何处理" aria-label="Permalink to &quot;1. 解析错误如何处理&quot;">​</a></h3><p>Godot 脚本编辑器会实时显示 KonadoScript 的语法和语义问题。无效内容仍可保存为 <code>.ks</code> 源文件，但不会刷新当前的运行时 <code>KonadoShot</code>；修复错误并再次保存后，资源加载器会自动重新编译，无需手动重新导入。</p><h3 id="_2-脚本文件编码问题" tabindex="-1">2. 脚本文件编码问题 <a class="header-anchor" href="#_2-脚本文件编码问题" aria-label="Permalink to &quot;2. 脚本文件编码问题&quot;">​</a></h3><p>确保脚本文件编码为UTF-8，否则可能出现乱码，默认情况下创建的脚本文件编码为UTF-8。</p><h3 id="_3-导出后的剧本保护" tabindex="-1">3. 导出后的剧本保护 <a class="header-anchor" href="#_3-导出后的剧本保护" aria-label="Permalink to &quot;3. 导出后的剧本保护&quot;">​</a></h3><p>导出项目时，Konado 会读取当前导出预设中 <code>Konado -&gt; Script Encryption Key</code> 的值，并自动加密已编译的 <code>.ks</code> 剧情数据。如果密钥为空或格式错误，Konado 会生成一个随机的 256 位密钥并用于本次构建。之后的导出会复用该密钥，除非开发者手动修改。</p><p>发布补丁或热更新时，基础包与更新包必须使用相同的导出预设和密钥。密钥保存在 <code>.godot/konado_export_credentials.cfg</code>，如果需要长期使用请自行备份。</p><p>本地导出时，Godot 终端会打印本次构建的完整密钥，便于开发者记录和排查问题。本功能用于避免通用工具从 PCK 中直接读取剧情明文，不能替代专用 DRM；能够针对性分析导出资源、客户端代码或运行时内存的攻击者仍可能恢复剧情内容。</p>',15)])])}const u=o(i,[["render",d]]);export{_ as __pageData,u as default};
